    "feature_onboard_process_id": "CollectionOnboarding",
    "collection_append_process_id": "CollectionAppending",
    "multipart_initiate_process_id": "S3InitiateMultipartUpload",
    "multipart_complete_process_id": "S3CompleteMultipartUpload",
    "feature_attributes_process_id": "FeatureAttributesExtraction",
    "tiles_from_feature_process_id": "TilesOnboardingFromExistingFeature",
    "tiles_metadata_process_id": "TilesMetaDataOnboarding"
};

for (const varName in expectedProcesses) {
    const expectedTitle = expectedProcesses[varName];
    const expectedId = pm.variables.get(varName);

    pm.test(expectedTitle + " exists with id {{" + varName + "}}", function () {
        const found = processes.find(p => p.id === expectedId);
        pm.expect(found, "No process with id " + expectedId).to.not.be.undefined;
        pm.expect(found.title).to.eql(expectedTitle);
    });
}

