// New run: clear values left from any previous run
pm.collectionVariables.unset("stac_collection_id");
pm.collectionVariables.unset("stac_catalog_item_name");
pm.collectionVariables.unset("stac_item_id");

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const body = pm.response.json();
const itemId = body.itemId || body.id || (body.result && body.result.itemId) || (body.result && body.result.id);

pm.test("Response gives the new catalog item id", function () {
    pm.expect(itemId).to.be.a("string");
});

pm.test("Item name is unique for this run", function () {
    pm.expect(body.result.itemName).to.match(/^qa-ogc-stac-\d+$/);
});

pm.test("Item is registered on the OGC resource server", function () {
    pm.expect(body.result.resourceServers).to.have.property("OGC");
    pm.expect(body.result.resourceServers.OGC.data.status).to.eql("created");
});

// The catalog item id becomes the STAC collection id
if (itemId) {
    pm.collectionVariables.set("stac_collection_id", itemId);
    pm.collectionVariables.set("stac_catalog_item_name", body.result.itemName);
}
console.log("Created STAC catalog item:", itemId, "-", body.result && body.result.itemName);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Body has 'processes' array", function () {
    const body = pm.response.json();
    pm.expect(body).to.have.property("processes");
    pm.expect(body.processes).to.be.an("array");
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

// ---------- Part 1: retry if the OGC server can't see the new item yet ----------
const maxTries = 6;                                   // 6 × 5 s = 30 s max
const tries = Number(pm.collectionVariables.get("presign_tries") || 0);
const notReadyYet = pm.response.code === 500 &&
                    pm.response.text().includes("Error fetching item metadata");
const willRetry = notReadyYet && tries < maxTries;

if (willRetry) {
    pm.collectionVariables.set("presign_tries", tries + 1);
    console.log("Item not visible to OGC server yet – retry " + (tries + 1) + " of " + maxTries);
    setTimeout(function () {}, 5000);                 // wait 5 seconds
    pm.execution.setNextRequest(pm.info.requestName); // run this same request again
} else {
    pm.collectionVariables.unset("presign_tries");    // reset the counter for next run
}

// ---------- Part 2: real tests – only on the final attempt ----------
if (!willRetry) {

    pm.test("Status code is 200", function () {
        pm.response.to.have.status(200);
    });

    // The presigned URL can sit anywhere in the body – search for it
    function findPresignedUrl(value) {
        if (typeof value === "string") {
            return value.includes("X-Amz-Signature") ? value : null;
        }
        if (value && typeof value === "object") {
            for (const key of Object.keys(value)) {
                const found = findPresignedUrl(value[key]);
                if (found) {
                    return found;
                }
            }
        }
        return null;
    }

    const body = pm.response.json();
    const presignedUrl = findPresignedUrl(body);

    pm.test("Response contains a presigned S3 URL", function () {
        pm.expect(presignedUrl, "No X-Amz-Signature URL found – check console").to.be.a("string");
    });

    pm.test("S3 object key is our item id + .gpkg", function () {
        const expectedKey = pm.variables.get("feature_resource_id") + ".gpkg";
        pm.expect(body.s3ObjectKeyName).to.eql(expectedKey);
    });

    pm.test("Response has jobID and status 'successful'", function () {
        pm.expect(body).to.have.property("jobID");
        pm.expect(body.status).to.eql("successful");
    });

    // Save values for step 04 (upload) and step 06 (onboarding)
    if (presignedUrl) {
        pm.collectionVariables.set("presigned_url", presignedUrl);
    } else {
        console.log("Execution response:", JSON.stringify(body, null, 2));
    }

    if (body.s3ObjectKeyName) {
        pm.collectionVariables.set("s3_object_key_name", body.s3ObjectKeyName);
    }
}

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

// OGC API Processes returns the job id in the body (jobID) and/or the Location header
const body = pm.response.json();
let jobId = body.jobID || body.jobId || body.id;

if (!jobId && pm.response.headers.get("Location")) {
    jobId = pm.response.headers.get("Location").split("/jobs/")[1];
}

pm.test("Response gives a job id", function () {
    pm.expect(jobId).to.be.a("string");
});

if (jobId) {
    pm.collectionVariables.set("feature_job_id", jobId);
}
console.log("Execution response:", JSON.stringify(body, null, 2));

pm.test("Job accepted: type PROCESS, status ACCEPTED", function () {
    const body = pm.response.json();
    pm.expect(body.type).to.eql("PROCESS");
    pm.expect(body.status).to.eql("ACCEPTED");
});

pm.test("Job belongs to the CollectionOnboarding process", function () {
    const body = pm.response.json();
    pm.expect(body.processId).to.eql(pm.variables.get("feature_onboard_process_id"));
});

