pm.test("Error format as per spec (type, title, detail)", function () {
    pm.expect(body.type).to.eql("Not Found");
    pm.expect(body.title).to.eql("Not Found");
    pm.expect(body).to.have.property("detail");
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const body = pm.response.json();
const maxTries = 12;                                  // 12 × 5 s = 1 minute max
const tries = Number(pm.collectionVariables.get("job_poll_tries") || 0);
const stillRunning = body.status === "ACCEPTED" || body.status === "RUNNING";

if (stillRunning && tries < maxTries) {
    // Job not finished yet → wait 5 seconds and run THIS request again
    pm.collectionVariables.set("job_poll_tries", tries + 1);
    console.log("Job is " + body.status + " – retry " + (tries + 1) + " of " + maxTries);
    setTimeout(function () {}, 5000);
    pm.execution.setNextRequest(pm.info.requestName);
} else {
    // Job finished (or we gave up) → reset the counter and check the result
    pm.collectionVariables.unset("job_poll_tries");

    pm.test("Status is for our job", function () {
        pm.expect(body.id).to.eql(pm.variables.get("feature_job_id"));
        pm.expect(body.process_id).to.eql(pm.variables.get("feature_onboard_process_id"));
        pm.expect(body.type).to.eql("PROCESS");
    });

    pm.test("Onboarding finished successfully", function () {
        pm.expect(body.status).to.eql("SUCCESSFUL");
        pm.expect(Number(body.progress)).to.eql(100);
        pm.expect(body).to.have.property("message");
    });
}

