const maxTries = 24;                                  // 24 × 5 s = 2 minutes max
const tries = Number(pm.collectionVariables.get("tiles_poll_tries") || 0);
const stillRunning = body.status === "ACCEPTED" || body.status === "RUNNING";

if (stillRunning && tries < maxTries) {
    // Job not finished yet -> wait 5 seconds and run THIS request again
    pm.collectionVariables.set("tiles_poll_tries", tries + 1);
    console.log("Tiles job is " + body.status + " - retry " + (tries + 1) + " of " + maxTries);
    setTimeout(function () {}, 5000);
    pm.execution.setNextRequest(pm.info.requestName);
} else {
    // Job finished (or we gave up) -> reset the counter and check the result
    pm.collectionVariables.unset("tiles_poll_tries");

    pm.test("Status is for our tiles job", function () {
        pm.expect(body.id).to.eql(pm.environment.get("tiles_job_id"));
        pm.expect(body.process_id).to.eql(pm.environment.get("tiles_from_feature_process_id"));
        pm.expect(body.type).to.eql("PROCESS");
    });

    pm.test("Tiles onboarding finished successfully", function () {
        pm.expect(body.status).to.eql("SUCCESSFUL");
        pm.expect(Number(body.progress)).to.eql(100);
    });
}

