// Collect all [lon, lat] points from any geometry
function collectPoints(coords, points) {
    if (typeof coords[0] === "number") {
        points.push(coords);
    } else {
        coords.forEach(function (c) { collectPoints(c, points); });
    }
    return points;
}

pm.test("Every record's geometry intersects the bbox (spec)", function () {
    body.features.forEach(function (f) {
        const pts = collectPoints(f.geometry.coordinates, []);
        const lons = pts.map(function (p) { return p[0]; });
        const lats = pts.map(function (p) { return p[1]; });
        const intersects = Math.min.apply(null, lons) <= box[2] && Math.max.apply(null, lons) >= box[0] &&
                           Math.min.apply(null, lats) <= box[3] && Math.max.apply(null, lats) >= box[1];
        pm.expect(intersects, "record " + f.id + " intersects bbox").to.be.true;
    });
});

